);

testbench:
`timescale 1ns/1ps

module priority_encoder_tb;
    reg  [3:0] in;          // Input to the DUT
    wire [1:0] code;        // Output from the DUT
    reg  [1:0] expected;    // Expected output
    integer errors;         // Count the number of test failures
    integer i;              // Loop variable

    // Instantiate the Device Under Test (DUT)
    priority_encoder dut (
        .in(in),
        .code(code)
    );

    initial begin
        errors = 0;
        $display("==========Testbench results==========");
        $display("=====================================");
        $display(" Test Input  | Expected | Output | Pass/Fail ");
        $display("-------------------------------------");

        // Iterate through all possible 4-bit input combinations (0 to 15)
        for(i = 0; i < 16; i = i + 1) begin
            in = i;
            #10;  // Wait for output to settle

            // Compute expected output based on the highest-order '1'
            if (in[3])
                expected = 2'b11;
            else if (in[2])
                expected = 2'b10;
            else if (in[1])
                expected = 2'b01;
            else if (in[0])
                expected = 2'b00;
            else
                expected = 2'b00;

            // Check if the output matches the expected value and display the result
            if (code === expected)
                $display("   %04b    |    %02b    |  %02b   |   Pass", in, expected, code);
            else begin
                $display("   %04b    |    %02b    |  %02b   |   Fail", in, expected, code);
                errors = errors + 1;
            end
        end

        $display("-------------------------------------");
        if (errors == 0)
            $display("All tests passed");
        else
            $display("Some tests failed");

        $finish;
    end
endmodule

module_header:
module fsm_3state (
    input clk, reset,
    output [1:0] state
);

testbench:
`timescale 1ns/1ps

module fsm_3state_tb;
    reg clk, reset;
    wire [1:0] state;
    integer errors, cycle;
    reg [1:0] expected_state;

    // Instantiate the DUT (Device Under Test)
    fsm_3state dut (
        .clk(clk),
        .reset(reset),
        .state(state)
    );

    // Clock generation: 10 time-unit period.
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    initial begin
        errors = 0;

        // Apply reset for one clock cycle.
        reset = 1;
        #10;          // Wait 10 time units.
        reset = 0;   // Release reset.

        // Optionally, check the state immediately after reset:
        #1; // small delay to allow state to settle
        if (state !== 2'b00) begin
            $display("Warning: state immediately after reset is not 00, got %02b", state);
        end

        // Display header for the testbench results.
        $display("==========Testbench results==========");
        $display("=====================================");
        $display(" Test Input  | Expected | Output | Pass/Fail ");
        $display("-------------------------------------");

        // After reset, on the first rising edge, the design transitions to state B (2'b01)
        expected_state = 2'b01;

        // Let the FSM run for several cycles.
        // The expected transitions now are:
        // Cycle 0: 2'b01, Cycle 1: 2'b10, Cycle 2: 2'b00, Cycle 3: 2'b01, etc.
        for (cycle = 0; cycle < 9; cycle = cycle + 1) begin
            @(posedge clk);
            #1; // small delay for state to settle
            if (state === expected_state)
                $display("   Cycle %0d  |    %02b    |  %02b  |   Pass", cycle, expected_state, state);
            else begin
                $display("   Cycle %0d  |    %02b    |  %02b  |   Fail", cycle, expected_state, state);
                errors = errors + 1;
            end

            // Update expected_state for the next cycle:
            // B (01) -> C (10), C (10) -> A (00), A (00) -> B (01)
            case(expected_state)
                2'b01: expected_state = 2'b10;
                2'b10: expected_state = 2'b00;
                2'b00: expected_state = 2'b01;
                default: expected_state = 2'b01;
            endcase
        end

        $display("-------------------------------------");
        if (errors == 0)
            $display("All tests passed");
        else
            $display("Some tests failed");
        $display("=====================================");
        $finish;
    end
endmodule

module_header:
module traffic_light (
    input clk, reset,
    output [2:0] light
);

testbench:
`timescale 1ns/1ps

module traffic_light_tb;
    reg clk, reset;
    wire [2:0] light;
    integer errors, cycle;
    reg [2:0] expected_light;

    // Instantiate the DUT (Device Under Test)
    traffic_light dut (
        .clk(clk),
        .reset(reset),
        .light(light)
    );

    // Clock generation: 10 ns period (toggle every 5 ns)
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    initial begin
        errors = 0;

        // Apply reset for 10 ns
        reset = 1;
        #10;
        reset = 0;
        #1;  // small delay for state to settle after reset

        // (Optional) Check initial state before any clock edge.
        // After reset, the FSM is in RED (3'b100).
        if (light !== 3'b100)
            $display("Warning: Initial state is not RED (expected 100), got %03b", light);

        // Display header for the testbench results.
        $display("==========Testbench results==========");
        $display("=====================================");
        $display(" Test Input  | Expected | Output | Pass/Fail ");
        $display("-------------------------------------");

        // After reset, the FSM is in RED.
        // On the first rising edge the FSM transitions from RED to GREEN.
        // Therefore, we expect the following sequence (sampled on each rising edge):
        // Cycle 0: GREEN (3'b001)
        // Cycle 1: YELLOW (3'b010)
        // Cycle 2: RED    (3'b100)
        // Cycle 3: GREEN  (3'b001)
        // ... and so on.
        expected_light = 3'b001; // set expected for Cycle 0

        // Let the FSM run for 9 cycles.
        for (cycle = 0; cycle < 9; cycle = cycle + 1) begin
            @(posedge clk);
            #1;  // small delay for the output to settle

            if (light === expected_light)
                $display("   Cycle %0d  |   %03b   | %03b  |   Pass", cycle, expected_light, light);
            else begin
                $display("   Cycle %0d  |   %03b   | %03b  |   Fail", cycle, expected_light, light);
                errors = errors + 1;
            end

            // Update expected_light based on the FSM transitions:
            // GREEN (001) -> YELLOW (010)
            // YELLOW (010) -> RED (100)
            // RED (100)    -> GREEN (001)
            case(expected_light)
                3'b001: expected_light = 3'b010;
                3'b010: expected_light = 3'b100;
                3'b100: expected_light = 3'b001;
                default: expected_light = 3'b001;
            endcase
        end

        $display("-------------------------------------");
        if (errors == 0)
            $display("All tests passed");
        else
            $display("Some tests failed");
        $display("=====================================");
        $finish;
    end
endmodule

module_header:
module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

testbench:
`timescale 1ns/1ps
module elevator_controller_tb;
    reg clk, reset;
    reg up_request, down_request;
    wire [1:0] state;

    integer errors;
    reg [1:0] expected;  // Expected state for each test

    // Instantiate the Elevator Controller.
    elevator_controller uut (
        .clk(clk),
        .reset(reset),
        .up_request(up_request),
        .down_request(down_request),
        .state(state)
    );

    // Clock generation: period = 10 time units.
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    initial begin
        errors = 0;

        // Display header.
        $display("==========Testbench results==========");
        $display("=====================================");
        $display(" Test Input           | Expected | Output | Pass/Fail ");
        $display("-------------------------------------");

        // --- Test 1: No Request ---
        reset = 1;  // Assert reset.
        up_request = 0;
        down_request = 0;
        #10;        // Hold reset for a couple cycles.
        reset = 0;
        @(posedge clk); #1;  // Wait for state update.
        expected = 2'b00;     // IDLE
        if (state === expected)
            $display(" No Request           |   %02b    |  %02b  |   Pass", expected, state);
        else begin
            $display(" No Request           |   %02b    |  %02b  |   Fail", expected, state);
            errors = errors + 1;
        end

        // --- Test 2: Up Request Only ---
        up_request = 1;
        down_request = 0;
        @(posedge clk); #1;
        expected = 2'b01;     // MOVING_UP
        if (state === expected)
            $display(" Up Request           |   %02b    |  %02b  |   Pass", expected, state);
        else begin
            $display(" Up Request           |   %02b    |  %02b  |   Fail", expected, state);
            errors = errors + 1;
        end

        // --- Test 3: Down Request Only ---
        up_request = 0;
        down_request = 1;
        @(posedge clk); #1;
        expected = 2'b00;     // MOVING_DOWN
        if (state === expected)
            $display(" Down Request         |   %02b    |  %02b  |   Pass", expected, state);
        else begin
            $display(" Down Request         |   %02b    |  %02b  |   Fail", expected, state);
            errors = errors + 1;
        end

        // --- Test 4: Both Requests Active ---
        up_request = 1;
        down_request = 1;
        @(posedge clk); #1;
        expected = 2'b01;     // Prioritize MOVING_UP when both are active.
        if (state === expected)
            $display(" Both Requests        |   %02b    |  %02b  |   Pass", expected, state);
        else begin
            $display(" Both Requests        |   %02b    |  %02b  |   Fail", expected, state);
            errors = errors + 1;
        end

        // --- Test 5: Transition from MOVING_UP to IDLE ---
        // Start with an up request then deassert it.
        up_request = 1;
        down_request = 0;
        @(posedge clk); #1;   // Should be MOVING_UP.
        expected = 2'b01;
        if (state !== expected) begin
            $display(" Up Req, then Idle    |   %02b    |  %02b  |   Fail", expected, state);
            errors = errors + 1;
        end
        // Now deassert up_request.
        up_request = 0;
        @(posedge clk); #1;
        expected = 2'b00;    // Should go back to IDLE.
        if (state === expected)
            $display(" Idle after Up Req    |   %02b    |  %02b  |   Pass", expected, state);
        else begin
            $display(" Idle after Up Req    |   %02b    |  %02b  |   Fail", expected, state);
            errors = errors + 1;
        end

        // --- Test 6: Transition from MOVING_DOWN to IDLE ---
        up_request = 0;
        down_request = 1;
        @(posedge clk); #1;   // Should be MOVING_DOWN.
        expected = 2'b10;
        if (state !== expected) begin
            $display(" Down Req, then Idle  |   %02b    |  %02b  |   Fail", expected, state);
            errors = errors + 1;
        end
        // Now deassert down_request.
        down_request = 0;
        @(posedge clk); #1;
        expected = 2'b00;    // Should return to IDLE.
        if (state === expected)
            $display(" Idle after Down Req  |   %02b    |  %02b  |   Pass", expected, state);
        else begin
            $display(" Idle after Down Req  |   %02b    |  %02b  |   Fail", expected, state);
            errors = errors + 1;
        end

        $display("-------------------------------------");
        if (errors == 0)
            $display("All tests passed");
        else
            $display("Some tests failed");
        $display("=====================================");
        $finish;
    end
endmodule

module_header:
module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

testbench:
`timescale 1ns/1ps

module vending_machine_tb;
    reg clk, reset;
    reg coin_inserted, item_selected;
    wire [1:0] state;

    integer errors = 0;
    reg [1:0] expected_state;

    // Instantiate the vending machine FSM
    vending_machine uut (
        .clk(clk),
        .reset(reset),
        .coin_inserted(coin_inserted),
        .item_selected(item_selected),
        .state(state)
    );

    // Clock generation: 10 time-unit period.
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    initial begin
        errors = 0;

        // Reset the system
        reset = 1;
        coin_inserted = 0;
        item_selected = 0;
        #10;
        reset = 0;

        $display("==========Testbench results==========");
        $display("=====================================");
        $display(" Coin | Item | Expected | Output | Pass/Fail ");
        $display("-------------------------------------");

        // Test cases
        run_test(1'b0, 1'b0, 2'b00); // IDLE state
        run_test(1'b1, 1'b0, 2'b01); // COLLECTING_COINS state
        run_test(1'b1, 1'b1, 2'b10); // DISPENSING_ITEM state
        run_test(1'b0, 1'b0, 2'b00); // Return to IDLE
        run_test(1'b1, 1'b0, 2'b01); // Insert coin again
        run_test(1'b0, 1'b0, 2'b00); // Remove coin, should return to IDLE

        $display("=====================================");
        if (errors == 0)
            $display("All tests passed");
        else
            $display("Some tests failed");
        $display("=====================================");
        $finish;
    end

    // Task to verify expected state
    task run_test;
        input reg test_coin_inserted, test_item_selected;
        input [1:0] exp_state;
        begin
            coin_inserted = test_coin_inserted;
            item_selected = test_item_selected;
            expected_state = exp_state;
            #10; // Wait for state transition

            if (state === expected_state) begin
                $display("  %b   |  %b   |    %02b     |   %02b   |  PASS", coin_inserted, item_selected, expected_state, state);
            end else begin
                $display("  %b   |  %b   |    %02b     |   %02b   |  FAIL", coin_inserted, item_selected, expected_state, state);
                errors = errors + 1;
            end
        end
    endtask

endmodule

