        $display("             | (AND / OR / XOR)     | (AND / OR / XOR)     |           ");
        $display("-------------------------------------");

        // Loop through the test cases.
        for (i = 0; i < 5; i = i + 1) begin
            a = test_a[i];
            b = test_b[i];
            #10;  // Wait for outputs to settle.

            // Compute the expected values.
            expected_and = a & b;
            expected_or  = a | b;
            expected_xor = a ^ b;

            // Check if all three outputs match the expected values.
            if ((and_out === expected_and) && (or_out === expected_or) &&
                (xor_out === expected_xor))
                $display("   %02h, %02h  |   %02h / %02h / %02h   |   %02h / %02h / %02h   |   Pass",
                         a, b, expected_and, expected_or, expected_xor,
