            else begin
                $display("   %02h, %02h  |   %02h / %02h / %02h   |   %02h / %02h / %02h   |   Fail",
                         a, b, expected_and, expected_or, expected_xor,
                         and_out, or_out, xor_out);
                errors = errors + 1;
            end
        end

        $display("-------------------------------------");
        if (errors == 0)
            $display("All tests passed");
        else
            $display("Some tests failed");
        $display("=====================================");
        $finish;
