  reg [3:0] B;    // Second BCD input (4 bits)
  reg Cin;        // Carry-in input (1 bit)
  wire [3:0] Sum; // BCD sum output (4 bits)
  wire Cout;      // Carry-out output (1 bit)

  integer i;      
  integer error = 0; 
  reg [4:0] expected_sum; 


